query:
SELECT id, enterpriseName, industry, website, region, status, createdAt, updatedAt FROM projects WHERE enterpriseName = '海豚知道';
SELECT COUNT(*) AS external_acceptance_user_count FROM users WHERE email LIKE '%acceptance%' OR name LIKE '%外部验收%' OR openId LIKE '%acceptance%';
SELECT p.id AS projectId, p.enterpriseName, (SELECT COUNT(*) FROM enterprise_geo_profiles e WHERE e.projectId=p.id) AS enterprise_profile_count, (SELECT COUNT(*) FROM geo_asset_sources s WHERE s.projectId=p.id) AS asset_source_count, (SELECT COUNT(*) FROM customer_cases c WHERE c.projectId=p.id) AS customer_case_count, (SELECT COUNT(*) FROM competitor_profiles cp WHERE cp.projectId=p.id AND cp.competitorName IN ('小鹅通','有赞教育')) AS named_competitor_count, (SELECT COUNT(*) FROM compliance_rules cr WHERE cr.projectId=p.id AND cr.enabled=1) AS compliance_rule_count, (SELECT COUNT(*) FROM content_style_profiles cs WHERE cs.projectId=p.id AND cs.enabled=1) AS content_style_count, (SELECT COUNT(*) FROM publish_strategies ps WHERE ps.projectId=p.id AND ps.enabled=1) AS publish_strategy_count, (SELECT COUNT(*) FROM questions q WHERE q.projectId=p.id AND q.enabled=1) AS question_count, (SELECT COUNT(*) FROM ai_responses ar WHERE ar.projectId=p.id) AS ai_response_count, (SELECT COUNT(*) FROM analysis_results an WHERE an.projectId=p.id) AS analysis_count, (SELECT COUNT(*) FROM geo_scores gs WHERE gs.projectId=p.id) AS geo_score_count, (SELECT COUNT(*) FROM optimization_tasks ot WHERE ot.projectId=p.id) AS task_count, (SELECT COUNT(*) FROM geo_articles ga WHERE ga.projectId=p.id) AS article_count, (SELECT COUNT(*) FROM geo_articles ga WHERE ga.projectId=p.id AND ga.generationBasis IS NOT NULL AND ga.factTraceability IS NOT NULL AND ga.consistencyCheck IS NOT NULL AND ga.citableSnippets IS NOT NULL) AS complete_article_count, (SELECT COUNT(*) FROM geo_article_quality_scores gqs WHERE gqs.projectId=p.id) AS article_quality_count, (SELECT COUNT(*) FROM geo_publish_records gpr WHERE gpr.projectId=p.id AND gpr.publishStatus='已发布') AS published_count, (SELECT COUNT(*) FROM reports r WHERE r.projectId=p.id) AS report_count FROM projects p WHERE p.enterpriseName='海豚知道';

